import '../../../../core/providers/core_providers.dart';
import '../../../../shared/domain/enums/account_type.dart';
import '../../domain/entities/account_entity.dart';
import '../providers/account_providers.dart';
import '../widgets/account_type_icon.dart';
import 'package:cursor_bhai/features/dashboard/presentation/providers/dashboard_providers.dart';
import '../../../../core/router/app_routes.dart';

class AccountFormScreen extends ConsumerStatefulWidget {
  const AccountFormScreen({super.key, this.accountId});

  final String? accountId;

  @override
  ConsumerState<AccountFormScreen> createState() => _AccountFormScreenState();
}

class _AccountFormScreenState extends ConsumerState<AccountFormScreen> {
  final _formKey = GlobalKey<FormState>();
  final _nameController = TextEditingController();
  final _balanceController = TextEditingController(text: '0');
  final _currencyController = TextEditingController(text: 'PKR');
  AccountType _accountType = AccountType.bank;
  bool _loading = false;

  bool get _isEdit => widget.accountId != null;

  @override
  void initState() {
    super.initState();
    if (_isEdit) _loadAccount();
  }

  Future<void> _loadAccount() async {
    final account =
        await ref.read(accountRepositoryProvider).getAccount(widget.accountId!);
    if (account != null && mounted) {
      _nameController.text = account.name;
      _balanceController.text = account.initialBalance.toString();
      setState(() {
        _accountType = account.accountType;
        _currencyController.text = account.currency;
      });
    }
  }

  @override
  void dispose() {
    _nameController.dispose();
    _balanceController.dispose();
    _currencyController.dispose();
    super.dispose();
  }

  Future<void> _save() async {
    if (!_formKey.currentState!.validate()) return;
    setState(() => _loading = true);
    final now = DateTime.now();
    final idGen = ref.read(idGeneratorProvider);
    final balance = double.tryParse(_balanceController.text) ?? 0;

    try {
      if (!_isEdit) {
        final entity = AccountEntity(
          id: idGen.newId(),
          name: _nameController.text.trim(),
          accountType: _accountType,
          currency: _currencyController.text.trim().toUpperCase(),
          initialBalance: balance,
          createdAt: now,
          updatedAt: now,
        );
        await ref.read(createAccountProvider)(entity);
      } else {
        final existing = await ref
            .read(accountRepositoryProvider)
            .getAccount(widget.accountId!);
        if (existing == null) throw StateError('Account not found');
        await ref.read(updateAccountProvider)(
          existing.copyWith(
            name: _nameController.text.trim(),
            accountType: _accountType,
            currency: _currencyController.text.trim().toUpperCase(),
            initialBalance: balance,
            updatedAt: now,
          ),
        );
      }
      // Invalidate relevant providers so UI updates immediately.
      ref.invalidate(accountsListProvider);
      ref.invalidate(netWorthProvider);

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(_isEdit ? 'Account updated' : 'Account created')),
        );
        await Future.delayed(const Duration(milliseconds: 300));
        // Navigate explicitly to the accounts list so the updated list is visible.
        context.go(AppRoutes.accounts);
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.toString())));
      }
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(_isEdit ? 'Edit account' : 'New account')),
      body: Form(
        key: _formKey,
        child: ListView(
          padding: const EdgeInsets.all(16),
          children: [
            TextFormField(
              controller: _nameController,
              textCapitalization: TextCapitalization.words,
              decoration: const InputDecoration(
                labelText: 'Account name',
                hintText: 'e.g. HBL Savings',
              ),
              validator: (v) =>
                  v == null || v.trim().isEmpty ? 'Name is required' : null,
            ),
            const SizedBox(height: 16),
            DropdownButtonFormField<AccountType>(
              initialValue: _accountType,
              decoration: const InputDecoration(labelText: 'Account type'),
              items: AccountType.values
                  .map(
                    (t) => DropdownMenuItem(
                      value: t,
                      child: Row(
                        children: [
                          Icon(accountTypeIcon(t), size: 20),
                          const SizedBox(width: 12),
                          Text(t.label),
                        ],
                      ),
                    ),
                  )
                  .toList(),
              onChanged: (v) => setState(() => _accountType = v ?? _accountType),
            ),
            const SizedBox(height: 16),
            TextFormField(
              controller: _currencyController,
              decoration: const InputDecoration(labelText: 'Currency'),
              validator: (v) =>
                  v == null || v.trim().isEmpty ? 'Currency is required' : null,
            ),
            const SizedBox(height: 16),
            TextFormField(
              controller: _balanceController,
              keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: const InputDecoration(
                labelText: 'Opening balance',
                helperText:
                    'Current balance is calculated from transactions — never stored.',
              ),
              validator: (v) {
                if (double.tryParse(v ?? '') == null) return 'Enter a valid number';
                return null;
              },
            ),
            const SizedBox(height: 32),
            FilledButton(
              onPressed: _loading ? null : _save,
              child: _loading
                  ? const SizedBox(
                      height: 22,
                      width: 22,
                      child: CircularProgressIndicator(strokeWidth: 2),
                    )
                  : Text(_isEdit ? 'Save changes' : 'Create account'),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../../../core/providers/core_providers.dart';
import '../../../../shared/domain/enums/account_type.dart';
import '../../domain/entities/account_entity.dart';
import '../providers/account_providers.dart';
import '../widgets/account_type_icon.dart';
import 'package:cursor_bhai/features/dashboard/presentation/providers/dashboard_providers.dart';
import '../../../../core/router/app_routes.dart';

class AccountFormScreen extends ConsumerStatefulWidget {
  const AccountFormScreen({super.key, this.accountId});

  final String? accountId;

  @override
  ConsumerState<AccountFormScreen> createState() => _AccountFormScreenState();
}

class _AccountFormScreenState extends ConsumerState<AccountFormScreen> {
  final _formKey = GlobalKey<FormState>();
  final _nameController = TextEditingController();
  final _balanceController = TextEditingController(text: '0');
  final _currencyController = TextEditingController(text: 'PKR');
  AccountType _accountType = AccountType.bank;
  bool _loading = false;

  // Consider empty string as not providing an id — treat as create mode.
  bool get _isEdit => widget.accountId != null && widget.accountId!.trim().isNotEmpty;

  @override
  void initState() {
    super.initState();
    if (_isEdit) _loadAccount();
  }

  Future<void> _loadAccount() async {
    if (widget.accountId == null || widget.accountId!.trim().isEmpty) return;
    final account = await ref.read(accountRepositoryProvider).getAccount(widget.accountId!);
    if (account == null) {
      // If account was not found for the given id, fall back to create mode.
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Account not found — creating new account')),
        );
      }
      return;
    }
    if (mounted) {
      _nameController.text = account.name;
      _balanceController.text = account.initialBalance.toString();
      setState(() {
        _accountType = account.accountType;
        _currencyController.text = account.currency;
      });
    }
  }

  @override
  void dispose() {
    _nameController.dispose();
    _balanceController.dispose();
    _currencyController.dispose();
    super.dispose();
  }

  Future<void> _save() async {
    if (!_formKey.currentState!.validate()) return;
    setState(() => _loading = true);
    final now = DateTime.now();
    final idGen = ref.read(idGeneratorProvider);
    final balance = double.tryParse(_balanceController.text) ?? 0;

    try {
      if (!_isEdit) {
        final entity = AccountEntity(
          id: idGen.newId(),
          name: _nameController.text.trim(),
          accountType: _accountType,
          currency: _currencyController.text.trim().toUpperCase(),
          initialBalance: balance,
          createdAt: now,
          updatedAt: now,
        );
        await ref.read(createAccountProvider)(entity);
      } else {
        final existing = await ref.read(accountRepositoryProvider).getAccount(widget.accountId!);
        if (existing == null) {
          // Gracefully show an error and abort update; user can retry as create.
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(content: Text('Account not found — cannot update')),
            );
          }
          return;
        }
        await ref.read(updateAccountProvider)(
          existing.copyWith(
            name: _nameController.text.trim(),
            accountType: _accountType,
            currency: _currencyController.text.trim().toUpperCase(),
            initialBalance: balance,
            updatedAt: now,
          ),
        );
      }
      // Invalidate relevant providers so UI updates immediately.
      ref.invalidate(accountsListProvider);
      ref.invalidate(netWorthProvider);

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(_isEdit ? 'Account updated' : 'Account created')),
        );
        await Future.delayed(const Duration(milliseconds: 300));
        // Navigate explicitly to the accounts list so the updated list is visible.
        context.go(AppRoutes.accounts);
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.toString())));
      }
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(_isEdit ? 'Edit account' : 'New account')),
      body: Form(
        key: _formKey,
        child: ListView(
          padding: const EdgeInsets.all(16),
          children: [
            TextFormField(
              controller: _nameController,
              textCapitalization: TextCapitalization.words,
              decoration: const InputDecoration(
                labelText: 'Account name',
                hintText: 'e.g. HBL Savings',
              ),
              validator: (v) =>
                  v == null || v.trim().isEmpty ? 'Name is required' : null,
            ),
            const SizedBox(height: 16),
            DropdownButtonFormField<AccountType>(
              initialValue: _accountType,
              decoration: const InputDecoration(labelText: 'Account type'),
              items: AccountType.values
                  .map(
                    (t) => DropdownMenuItem(
                      value: t,
                      child: Row(
                        children: [
                          Icon(accountTypeIcon(t), size: 20),
                          const SizedBox(width: 12),
                          Text(t.label),
                        ],
                      ),
                    ),
                  )
                  .toList(),
              onChanged: (v) => setState(() => _accountType = v ?? _accountType),
            ),
            const SizedBox(height: 16),
            TextFormField(
              controller: _currencyController,
              decoration: const InputDecoration(labelText: 'Currency'),
              validator: (v) =>
                  v == null || v.trim().isEmpty ? 'Currency is required' : null,
            ),
            const SizedBox(height: 16),
            TextFormField(
              controller: _balanceController,
              keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: const InputDecoration(
                labelText: 'Opening balance',
                helperText:
                    'Current balance is calculated from transactions — never stored.',
              ),
              validator: (v) {
                if (double.tryParse(v ?? '') == null) return 'Enter a valid number';
                return null;
              },
            ),
            const SizedBox(height: 32),
            FilledButton(
              onPressed: _loading ? null : _save,
              child: _loading
                  ? const SizedBox(
                      height: 22,
                      width: 22,
                      child: CircularProgressIndicator(strokeWidth: 2),
                    )
                  : Text(_isEdit ? 'Save changes' : 'Create account'),
            ),
          ],
        ),
      ),
    );
  }
}

