class PSXHolding {
  final String symbol;
  final double quantity;
  final double averageBuyPrice;

  PSXHolding({required this.symbol, required this.quantity, required this.averageBuyPrice});

  double investedValue() => quantity * averageBuyPrice;
}

class StockQuote {
  final String symbol;
  final double price;
  final DateTime fetchedAt;

  StockQuote({required this.symbol, required this.price, required this.fetchedAt});

  Map<String, dynamic> toJson() => {'symbol': symbol, 'price': price, 'fetchedAt': fetchedAt.toIso8601String()};

  factory StockQuote.fromJson(Map<String, dynamic> json) => StockQuote(
        symbol: json['symbol'] as String,
        price: (json['price'] as num).toDouble(),
        fetchedAt: DateTime.parse(json['fetchedAt'] as String),
      );
}

class PortfolioSummary {
  final double totalInvested;
  final double totalMarketValue;
  final double totalPnL;

  PortfolioSummary({required this.totalInvested, required this.totalMarketValue}) : totalPnL = totalMarketValue - totalInvested;

  double get pnlPercent => totalInvested == 0 ? 0 : (totalPnL / totalInvested) * 100;
}

import 'dart:async';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../repositories/stock_repository.dart';
import '../models/stock_models.dart';

final stockRepositoryProvider = Provider<StockRepository>((ref) {
  final repo = StockRepository();
  ref.onDispose(() => repo.dispose());
  return repo;
});

// User-configurable watchlist
final watchlistProvider = StateProvider<List<String>>((ref) => ['HUBC', 'ENGRO', 'MARI', 'OGDC', 'FFC']);

// Periodic refresher: fetch all watchlist symbols every 30s
final psxAutoRefreshProvider = Provider<void>((ref) {
  final repo = ref.read(stockRepositoryProvider);
  Timer? timer;
  Future<void> tick() async {
    try {
      final list = ref.read(watchlistProvider);
      if (list.isNotEmpty) await repo.fetchSymbols(list);
    } catch (_) {}
  }

  // initial fetch
  tick();
  timer = Timer.periodic(const Duration(seconds: 30), (_) => tick());

  ref.onDispose(() {
    timer?.cancel();
  });
  return null;
});

// Single symbol quote provider (uses repository caching)
final stockPriceProvider = FutureProvider.family<StockQuote, String>((ref, symbol) async {
  final repo = ref.read(stockRepositoryProvider);
  final q = await repo.getQuote(symbol);
  return q;
});

// Portfolio summary computed from existing holdings provider (from portfolio_provider.dart)
final portfolioSummaryProvider = FutureProvider<PortfolioSummary>((ref) async {
  // ensure auto refresh runs
  ref.read(psxAutoRefreshProvider);
  final repo = ref.read(stockRepositoryProvider);
  // holdingsProvider is defined elsewhere; use it
  final holdings = ref.read(holdingsProvider);
  if (holdings.isEmpty) return PortfolioSummary(totalInvested: 0, totalMarketValue: 0);
  final symbols = holdings.map((h) => h.symbol).toSet().toList();
  final quotes = await repo.fetchSymbols(symbols);
  double totalInvested = 0;
  double totalMarket = 0;
  for (final h in holdings) {
    final invested = h.totalInvestment; // existing StockHolding model has totalInvestment
    totalInvested += invested;
    final quote = quotes[h.symbol];
    final price = quote?.price ?? repo.snapshot()[h.symbol]?.price ?? 0.0;
    totalMarket += h.quantity * price;
  }
  return PortfolioSummary(totalInvested: totalInvested, totalMarketValue: totalMarket);
});

import 'dart:async';
import 'package:flutter/widgets.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../repositories/stock_repository.dart';
import '../models/stock_models.dart';
import '../shared/providers/portfolio_provider.dart';

final stockRepositoryProvider = Provider<StockRepository>((ref) {
  final repo = StockRepository();
  ref.onDispose(() => repo.dispose());
  return repo;
});

// User-configurable watchlist
final watchlistProvider = StateProvider<List<String>>((ref) => ['HUBC', 'ENGRO', 'MARI', 'OGDC', 'FFC']);

// Lifecycle-aware refresher: pauses when app is backgrounded
class _AutoRefresher with WidgetsBindingObserver {
  final Ref ref;
  final StockRepository repo;
  Timer? _timer;
  bool _running = false;

  _AutoRefresher(this.ref, this.repo) {
    WidgetsBinding.instance.addObserver(this);
    _start();
  }

  void _start() {
    if (_running) return;
    _running = true;
    // initial tick
    _tick();
    _timer = Timer.periodic(const Duration(seconds: 30), (_) => _tick());
  }

  void _stop() {
    _timer?.cancel();
    _timer = null;
    _running = false;
  }

  Future<void> _tick() async {
    try {
      final list = ref.read(watchlistProvider);
      if (list.isNotEmpty) await repo.fetchSymbols(list);
    } catch (e) {
      // swallow errors; repository will fallback to cache
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.paused || state == AppLifecycleState.inactive) {
      _stop();
    } else if (state == AppLifecycleState.resumed) {
      _start();
    }
  }

  void dispose() {
    _stop();
    try {
      WidgetsBinding.instance.removeObserver(this);
    } catch (_) {}
  }
}

final psxAutoRefreshProvider = Provider<void>((ref) {
  final repo = ref.read(stockRepositoryProvider);
  final refresher = _AutoRefresher(ref, repo);
  ref.onDispose(() => refresher.dispose());
  return null;
});

// Single symbol quote provider (uses repository caching)
final stockPriceProvider = FutureProvider.family<StockQuote, String>((ref, symbol) async {
  final repo = ref.read(stockRepositoryProvider);
  final q = await repo.getQuote(symbol);
  return q;
});

// Portfolio summary computed from existing holdings provider (from portfolio_provider.dart)
final portfolioSummaryProvider = FutureProvider<PortfolioSummary>((ref) async {
  // ensure auto refresh runs
  ref.read(psxAutoRefreshProvider);
  final repo = ref.read(stockRepositoryProvider);
  // holdingsProvider is defined elsewhere; use it
  final holdings = ref.read(holdingsProvider);
  if (holdings.isEmpty) return PortfolioSummary(totalInvested: 0, totalMarketValue: 0);
  final symbols = holdings.map((h) => h.symbol).toSet().toList();
  final quotes = await repo.fetchSymbols(symbols);
  double totalInvested = 0;
  double totalMarket = 0;
  for (final h in holdings) {
    final invested = h.totalInvestment; // existing StockHolding model has totalInvestment
    totalInvested += invested;
    final quote = quotes[h.symbol];
    final price = quote?.price ?? repo.snapshot()[h.symbol]?.price ?? 0.0;
    totalMarket += h.quantity * price;
  }
  return PortfolioSummary(totalInvested: totalInvested, totalMarketValue: totalMarket);
});

import 'dart:convert';
import 'package:flutter/foundation.dart';
import '../services/psx_service.dart';
import '../models/stock_models.dart';
import '../core/storage/storage_utils.dart';
import 'dart:async';
import 'package:flutter/material.dart';

class StockRepository {
  final PSXService _service;
  final Map<String, StockQuote> _cache = {}; // in-memory cache
  static const _cacheKey = 'psx_quote_cache_v1';

  StockRepository({PSXService? service}) : _service = service ?? PSXService() {
    _loadCache();
  }

  Future<void> _loadCache() async {
    try {
      final raw = await StorageUtils.safeLoadPrefsString(_cacheKey);
      if (raw == null) return;
      final Map<String, dynamic> decoded = jsonDecode(raw) as Map<String, dynamic>;
      decoded.forEach((k, v) {
        try {
          final sq = StockQuote.fromJson(v as Map<String, dynamic>);
          _cache[k] = sq;
        } catch (_) {}
      });
    } catch (e) {
      debugPrint('StockRepository._loadCache failed: $e');
    }
  }

  Future<void> _saveCache() async {
    try {
      final map = _cache.map((k, v) => MapEntry(k, v.toJson()));
      await StorageUtils.safeSavePrefsString(_cacheKey, jsonEncode(map));
    } catch (e) {
      debugPrint('StockRepository._saveCache failed: $e');
    }
  }

  /// Get quote from cache if fresh (<=30s) or fetch new
  Future<StockQuote> getQuote(String symbol, {Duration maxAge = const Duration(seconds: 30)}) async {
    final s = symbol.toUpperCase();
    final cached = _cache[s];
    final now = DateTime.now();
    if (cached != null && now.difference(cached.fetchedAt) <= maxAge) {
      return cached;
    }
    try {
      final fetched = await _service.fetchLatestPrice(s);
      _cache[s] = fetched;
      // fire-and-forget cache save
      _saveCache();
      return fetched;
    } catch (e) {
      if (cached != null) return cached; // fallback
      rethrow;
    }
  }

  /// Fetch multiple symbols in parallel and update cache. Returns map of symbol->quote for successes.
  Future<Map<String, StockQuote>> fetchSymbols(List<String> symbols) async {
    final results = <String, StockQuote>{};
    final unique = symbols.map((s) => s.toUpperCase()).toSet().toList();
    final invalids = <String>[];
    final futures = unique.map((s) async {
      try {
        final q = await getQuote(s);
        results[s] = q;
      } catch (e) {
        debugPrint('fetchSymbols failed for $s: $e');
        // detect invalid symbol exception
        try {
          if (e is Exception && e.toString().contains('InvalidSymbolException')) {
            invalids.add(s);
          }
        } catch (_) {}
      }
    });
    await Future.wait(futures);
    if (invalids.isNotEmpty) {
      throw InvalidSymbolsException(invalidSymbols: invalids);
    }
    return results;
  }

  /// Return in-memory snapshot of cache
  Map<String, StockQuote> snapshot() => Map<String, StockQuote>.from(_cache);

  void dispose() {
    try {
      _service.dispose();
    } catch (_) {}
  }
}

class InvalidSymbolsException implements Exception {
  final List<String> invalidSymbols;
  InvalidSymbolsException({required this.invalidSymbols});
  @override
  String toString() => 'InvalidSymbolsException: ${invalidSymbols.join(",")}';
}

